(function(){'use strict';
/* Business Tools Database generator — jahdb-business-tools-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-BIZ-';
var SRC='public';
var RECORD_KIND='business tool record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"brief":"Spreadsheets are the universal business computer — grids of cells holding numbers, text, and formulas that recalculate instantly, used for everything from budgets to scientific models.","examples":["A small business tracks monthly cash flow: income rows, expense rows, a profit formula, and a chart — updated in minutes each month.","A sales manager's pipeline sheet uses filters and conditional formatting to flag deals over $50K closing this quarter."],"history":["VisiCalc (1979) invented the electronic spreadsheet; Lotus 1-2-3 (1983) made the IBM PC a business machine; Excel (1985/87) won the war.","Google Sheets (2006) moved spreadsheets to the cloud with real-time collaboration — the second revolution."],"points":["Cells hold values or formulas; formulas start with = and reference other cells (A1, $B$2), recalculating automatically when inputs change.","Absolute ($A$1) vs relative (A1) references control what moves when a formula is copied — the single most important spreadsheet skill.","Core functions: SUM, AVERAGE, IF, VLOOKUP/XLOOKUP, COUNTIF, SUMIF — a few dozen functions cover 95% of business use.","Formatting (numbers, dates, currency), sorting, filtering, and conditional formatting turn raw grids into readable reports.","Collaboration: cloud sheets allow simultaneous editing, comments, and version history — the end of emailing 'final_v3.xlsx'."],"qa":[["What is the difference between relative and absolute references?","Relative (A1) shifts when copied; absolute ($A$1) stays fixed — use $ to lock rows, columns, or both when copying formulas."],["What replaced emailing spreadsheet versions?","Cloud collaboration (Google Sheets, Excel Online) — one live file, simultaneous editors, full version history."],["Why do businesses still run on spreadsheets?","Flexibility: a spreadsheet models anything in minutes with no programming — the original no-code tool."]],"title":"Spreadsheets: The Universal Business Tool","uses":["Budgeting and forecasting: the default financial modeling surface.","Lists and tracking: inventories, pipelines, project tasks.","Quick analysis: sorting, filtering, and charting ad-hoc data."]},{"brief":"Spreadsheet formulas turn static grids into living models — functions, logic, and lookups that compute answers from raw data.","examples":["=IF(B2>100000,\"Enterprise\",\"SMB\") classifies every customer row by deal size automatically.","=XLOOKUP(A2,Products!A:A,Products!C:C) pulls each order's unit price from the product table."],"history":["Early formulas were arithmetic; Lotus added @functions; Excel's function library grew to 400+; XLOOKUP (2019) finally replaced VLOOKUP.","Array formulas and dynamic arrays (Excel 365) turned formulas into mini-programs operating on whole ranges."],"points":["Logic functions (IF, AND, OR, NOT, IFS) branch calculations — the foundation of business rules in sheets.","Lookup functions (VLOOKUP, HLOOKUP, XLOOKUP, INDEX+MATCH) join data across tables — the spreadsheet's database operation.","Aggregation (SUMIFS, COUNTIFS, AVERAGEIFS) summarizes by criteria — 'total sales per region per quarter' in one formula.","Text functions (LEFT, RIGHT, MID, TEXTJOIN, SPLIT) clean and reshape messy data.","Error handling (IFERROR, IFNA) keeps models readable when lookups miss — professional sheets never show raw #N/A to users."],"qa":[["Why use XLOOKUP instead of VLOOKUP?","XLOOKUP searches any direction, defaults to exact match, and returns whole rows — VLOOKUP only searches left-to-right with approximate match by default."],["What are dynamic arrays?","Formulas that spill results into neighboring cells automatically — one formula, many results, no copy-down."],["How do you debug a complex formula?","Evaluate step by step (Formula Auditing), break it into helper columns, and check each function's inputs separately."]],"title":"Formulas and Functions","uses":["Financial models: cascading calculations from assumptions to results.","Data cleaning: reshaping exports into usable tables.","Reporting: live summaries that update with the data."]},{"brief":"PivotTables summarize thousands of rows in seconds — drag fields to rows, columns, and values to slice data by any dimension without writing formulas.","examples":["A 50,000-row sales export becomes a region-by-quarter revenue summary with two drags — then a slicer filters it to the West region.","An HR analyst pivots headcount by department and level, spotting that Engineering's contractor ratio doubled."],"history":["PivotTables debuted in Lotus Improv (1991) and Excel (1994), democratizing OLAP-style analysis for non-programmers.","Power Pivot and modern data models extended pivots to millions of rows and multiple related tables."],"points":["Rows, Columns, Values, Filters: the four zones — drag a field to Values to aggregate it (sum, count, average), to Rows/Columns to group by it.","Grouping dates by month/quarter/year turns transaction lists into time series instantly.","Slicers and timelines add clickable filters — turning a pivot into an interactive dashboard.","Calculated fields and Power Pivot DAX measures extend pivots to ratios, running totals, and year-over-year growth.","Refresh discipline: pivots snapshot the source — refresh after data changes, and use Tables (not loose ranges) as sources so new rows are included."],"qa":[["When should you use a PivotTable instead of formulas?","For ad-hoc exploration and summaries of large datasets — pivots answer 'by X, by Y' questions in seconds without formula engineering."],["What is a slicer?","A visual filter button panel for pivots and charts — click to filter the whole report interactively."],["Why base pivots on Excel Tables?","Because Tables auto-expand — new data rows are included on refresh, while plain ranges silently exclude them."]],"title":"PivotTables and Data Analysis","uses":["Sales analysis: slicing revenue by any dimension on demand.","HR and operations: headcount, throughput, and quality summaries.","Executive dashboards: interactive summaries without code."]},{"brief":"Word processors turn blank pages into proposals, contracts, and reports — with styles, templates, and collaboration that keep long documents consistent.","examples":["A consulting proposal uses heading styles, a generated table of contents, and page numbers — reformatting 60 pages takes one style change.","A contract redlines in Track Changes: each party's edits in their color, accepted or rejected one by one."],"history":["WordStar (1978) and WordPerfect (1980s) ruled DOS; Microsoft Word (1983/89) won Windows; Google Docs (2006) brought real-time co-editing.","Styles-based formatting (vs manual bolding) was the professional leap — structure separated from appearance."],"points":["Styles (Heading 1, Normal, Quote) are the core discipline — format once, apply everywhere, generate TOCs and outlines automatically.","Templates enforce branding and structure: letterheads, reports, and proposals start from controlled templates, not blank pages.","Track Changes + comments enable multi-party review — every edit attributed, every decision recorded.","Long-document tools: sections, headers/footers per section, footnotes, cross-references, indexes, and mail merge.","Cloud collaboration: simultaneous editing, suggestion mode, and version history replaced round-trip email attachments."],"qa":[["Why use styles instead of manual formatting?","Consistency and automation — one style change reformats the whole document, and TOCs/outlines generate from heading styles."],["What is the difference between Track Changes and comments?","Track Changes records text edits (insertions/deletions); comments are margin notes discussing the text without altering it."],["What is mail merge?","Generating personalized documents (letters, labels, envelopes) by merging a template with a data list — names, addresses, amounts."]],"title":"Word Processing","uses":["Proposals and reports: structured long documents.","Contracts: redlined multi-party negotiation.","Templates: branded, repeatable business documents."]},{"brief":"Presentation software turns ideas into slide decks — visual narratives for pitches, training, and status — where design discipline matters more than effects.","examples":["A startup pitch deck runs 12 slides: problem, solution, traction, market, team, ask — one idea per slide, minimal text.","A quarterly business review uses the same template company-wide: metrics, wins, risks, next steps — comparable across teams."],"history":["PowerPoint (1987, then Microsoft) standardized the deck; Keynote (2003) raised design expectations; Google Slides (2006) enabled co-editing.","The 'death by PowerPoint' backlash produced modern discipline: fewer words, more visuals, story structure."],"points":["One idea per slide, minimal text — slides support the speaker; the deck is not the document (write the document separately).","Master slides and templates enforce fonts, colors, and layouts — brand consistency without per-slide fiddling.","Visuals over bullets: charts, diagrams, and images communicate faster than text walls.","Presenter tools: speaker notes, presenter view, and rehearsal timers separate what the audience sees from what the speaker needs.","Remote presenting: screen share, live captions, and recorded narrations adapted decks to video-first meetings."],"qa":[["What is the biggest presentation mistake?","Reading text-heavy slides aloud — the audience reads faster than you speak; slides should visualize, not duplicate, your words."],["What are master slides?","Template layouts defining fonts, colors, and placeholders — change the master and every slide updates."],["When should you send the deck vs present it?","Present the visual deck live; send a separate written document for pre-reads — a presentation is not a report."]],"title":"Presentation Software","uses":["Sales pitches: narrative decks that sell.","Status reviews: comparable templated updates.","Training: visual lessons with speaker notes."]},{"brief":"Email remains business's official record — and its biggest time sink — tamed by triage systems, filters, templates, and knowing when not to email.","examples":["A manager processes 200 daily emails with inbox-zero triage: delete, delegate, respond (2 min), defer, do — twice a day, not all day.","A support team runs shared inboxes with assignment, collision detection, and canned responses — email as a ticketing system."],"history":["Corporate email (1990s, Exchange/Outlook) replaced memos and faxes; Gmail (2004) brought search-first webmail; Slack-era chat reduced but never killed email.","Email overload spawned GTD, inbox zero, and the modern etiquette of short, structured messages."],"points":["Triage, don't graze: process email in batches — delete, delegate, 2-minute reply, defer to task list, or do now.","Filters and rules auto-file newsletters, notifications, and CCs — the inbox holds only mail addressed to you.","Templates (canned responses) standardize frequent replies — proposals, follow-ups, support answers — saving hours weekly.","Search beats folders: modern email is a searchable database; archive everything, find anything.","Know the alternatives: chat for quick questions, docs for collaboration, meetings for conflict — email for records and formal requests."],"qa":[["What is inbox zero?","A triage discipline: the inbox is a processing station, not storage — every message is deleted, delegated, answered, deferred, or done."],["When should you not use email?","Urgent matters (call), quick questions (chat), collaborative drafting (docs), sensitive topics (in person) — email is for records and async formality."],["How do teams share an inbox?","Shared-mailbox tools with assignment, internal notes, and collision warnings — turning email into a managed queue."]],"title":"Email Management","uses":["Official record: decisions and commitments in writing.","External communication: the universal business protocol.","Support queues: shared inboxes as lightweight ticketing."]},{"brief":"Calendars and scheduling tools coordinate time — the scarcest business resource — across people, rooms, and time zones.","examples":["A 50-person all-hands is scheduled with a poll finding the one overlapping free hour across four time zones.","A consultant's booking page lets clients self-schedule 30-minute calls — no email ping-pong, buffers between meetings automatic."],"history":["Paper planners gave way to Outlook/Exchange (1990s); Google Calendar (2006) made sharing effortless; scheduling links (Calendly, 2013) killed the 'what time works' email.","Time-zone-aware scheduling became essential as teams went global and remote."],"points":["Shared calendars show free/busy without exposing details — the basis of all meeting scheduling.","Scheduling links (Calendly-style) let others book within your rules: buffers, limits, time zones handled automatically.","Time blocking reserves calendar for deep work — the calendar is a plan, not just a record of others' requests.","Meeting hygiene: agendas, default 25/50-minute lengths, and no-meeting blocks protect productive time.","Resource calendars manage rooms, equipment, and shared assets — booking the projector with the meeting."],"qa":[["What is time blocking?","Scheduling your own work on the calendar like a meeting — protecting focus time from others' requests."],["Why default to 25/50 instead of 30/60 minutes?","To build in buffers — back-to-back meetings without breaks destroy afternoons."],["How do scheduling links work?","You define availability rules once; invitees pick from your real free slots — time zones converted automatically."]],"title":"Calendars and Scheduling","uses":["Meeting coordination: finding time across busy people.","Client booking: self-service appointment scheduling.","Focus protection: time-blocking deep work."]},{"brief":"Project management software turns plans into trackable work — tasks, owners, deadlines, and dependencies visible to the whole team.","examples":["A product launch runs in Asana: 120 tasks across design, engineering, marketing — dependencies show that packaging can't start before the dieline is approved.","A construction PM tracks 400 activities in MS Project with critical-path analysis — the three-week delay's source is visible instantly."],"history":["Gantt charts (1910s) and PERT (1950s) were paper; MS Project (1984) digitized them; web tools (Basecamp 2004, Asana 2011, Monday) made PM collaborative.","Agile tools (Jira, 2002) split project tracking into a software-specific discipline."],"points":["Tasks need owners and due dates — unowned, undated tasks are wishes, not plans.","Dependencies (finish-to-start, etc.) model reality: the critical path — the longest dependency chain — sets the earliest finish.","Views serve roles: list/board for doers, timeline/Gantt for planners, calendar for deadlines, dashboards for stakeholders.","Templates standardize repeatable projects — client onboarding, product launches — so nothing is forgotten.","Status discipline: weekly updates, blocked flags, and % complete turn the tool from a graveyard into a radar."],"qa":[["What is the critical path?","The longest chain of dependent tasks — its length sets the project's earliest finish; delays on it delay everything."],["What is the difference between Asana and MS Project?","Asana/Monday are collaborative task trackers for teams; MS Project is a professional scheduler with deep critical-path and resource analysis."],["Why do project tools become graveyards?","Because updating feels like overhead — the fix is ritual: weekly reviews where the plan is the agenda."]],"title":"Project Management Software","uses":["Cross-functional projects: one plan visible to all.","Client work: transparent timelines and deliverables.","Portfolio view: leadership seeing all projects' health."]},{"brief":"Gantt charts map tasks against time — bars showing duration, position showing schedule, links showing dependencies — the classic project visualization.","examples":["A website redesign Gantt shows design (weeks 1-3), build (3-6), content (4-7), QA (7-8) — the overlap of build and content visible at a glance.","A manufacturing shutdown Gantt sequences 200 maintenance tasks across a 10-day outage — the critical path highlighted in red."],"history":["Henry Gantt's charts (1910s) scheduled WWI production; computerized in the 1980s; now one view among many in modern PM tools.","Critical-path method (1950s, DuPont) added the math of dependencies to Gantt's bars."],"points":["Bars encode duration and timing; milestones (diamonds) mark key dates; links show dependencies — the grammar of the chart.","The critical path (usually red) is the sequence determining project end — float/slack elsewhere is scheduling freedom.","Baselines snapshot the plan — comparing baseline vs actual bars shows slippage visually.","Resource views overlay who's doing what — overallocation glows where one person has three simultaneous tasks.","Gantts suit waterfall-style planned work; they fight agile's emergent planning — choose the view for the methodology."],"qa":[["What is float (slack)?","How much a task can slip without delaying the project — zero float means it's on the critical path."],["What is a baseline?","A saved snapshot of the original plan — the reference that makes 'we're 2 weeks behind' a visible fact."],["When are Gantt charts the wrong tool?","For exploratory/agile work where tasks emerge — Gantts assume the plan is knowable upfront."]],"title":"Gantt Charts","uses":["Construction and events: deadline-driven sequenced work.","Manufacturing shutdowns: minute-planned outages.","Executive reporting: the plan vs actual story."]},{"brief":"Kanban boards visualize workflow as columns — To Do, Doing, Done — limiting work in progress so teams finish work instead of starting it.","examples":["A support team's board: New → Triaged → In Progress → Waiting on Customer → Resolved — the WIP limit of 3 per agent stops cherry-picking.","A marketing board moves campaigns from Ideas → In Production → Review → Launched — the 'Review' column's pileup reveals the bottleneck."],"history":["Toyota's kanban (1950s) managed parts flow; David Anderson (2000s) adapted it to knowledge work; Trello (2011) made boards mainstream.","WIP limits — the core discipline — came from lean manufacturing's war on overproduction."],"points":["Columns are workflow states; cards are work items — the board makes the invisible flow of knowledge work visible.","WIP limits cap items per column — finishing beats starting; limits expose bottlenecks instead of hiding them in queues.","Pull, don't push: new work enters only when capacity frees — the opposite of assigning piles of tasks.","Policies per column ('Done means tested and documented') make quality explicit.","Metrics: lead time, cycle time, and throughput turn the board into a continuous-improvement instrument."],"qa":[["What is WIP and why limit it?","Work in progress — limiting it forces finishing over starting, exposing bottlenecks and cutting lead times."],["What is the difference between kanban and scrum boards?","Kanban is continuous flow with WIP limits; scrum boards track a fixed sprint backlog — different planning rhythms, similar boards."],["What does 'pull' mean in kanban?","Team members pull the next card when they have capacity — work is never pushed onto overloaded people."]],"title":"Kanban Boards","uses":["Support and ops: continuous incoming work.","Content pipelines: ideas to published.","Personal productivity: visualizing your own workload."]},{"brief":"CRM systems track every customer interaction — contacts, deals, emails, support tickets — turning relationships into a managed pipeline instead of scattered memory.","examples":["A sales rep opens the CRM to see the full history: last call notes, open quote, support tickets — before dialing the renewal.","Marketing scores leads in the CRM: website visits + email opens + firm size = hot leads routed to sales automatically."],"history":["Rolodexes and ACT! (1987) digitized contacts; Salesforce (1999) put CRM in the cloud; modern CRMs unified sales, marketing, and service.","CRM succeeded when it stopped being a data-entry burden and started being the place work happens."],"points":["The contact/company record is the hub — every email, call, deal, and ticket attaches to it, building institutional memory.","Pipeline stages (prospect → qualified → proposal → closed) with probabilities produce forecasts — the sales leader's radar.","Automation: lead routing, follow-up sequences, and task creation keep deals moving without manual babysitting.","Reporting answers: conversion rates, cycle length, rep activity — the metrics of the sales machine.","Adoption is the risk: CRMs fail when reps see data entry without value — mobile access and email integration fix it."],"qa":[["What is a sales pipeline?","The staged process deals move through (prospect to close) — tracked in CRM with probabilities for forecasting."],["What is lead scoring?","Ranking prospects by fit and engagement so sales focuses on the hottest leads first."],["Why do CRM implementations fail?","When they're designed for management reporting instead of helping reps sell — adoption dies without rep value."]],"title":"CRM Systems","uses":["Sales management: pipeline, forecasting, and coaching.","Marketing: lead capture, scoring, and nurturing.","Service: full customer history at every touch."]},{"brief":"Accounting software records every dollar — the general ledger, payables, receivables, and financial statements — keeping the books audit-ready.","examples":["A bakery's QuickBooks records daily sales, supplier bills, and payroll — the P&L and balance sheet generate in one click at month-end.","An agency's Xero auto-imports bank transactions daily; the bookkeeper categorizes and reconciles in minutes."],"history":["Spreadsheets were the first digital ledgers; QuickBooks (1983) brought double-entry to small business; cloud accounting (Xero 2006) automated bank feeds.","Audit trails and role permissions turned accounting software into a control system, not just a calculator."],"points":["Double-entry is the foundation: every transaction debits and credits equal amounts — the books always balance or something is wrong.","Chart of accounts organizes income, expenses, assets, liabilities, equity — set it up right once, reporting works forever.","Bank feeds auto-import transactions; rules categorize recurring items — reconciliation becomes exception-handling.","Financial statements (P&L, balance sheet, cash flow) generate from the ledger — the language of business health.","Controls: user roles, approval workflows, and immutable audit trails satisfy accountants and auditors."],"qa":[["What is double-entry bookkeeping?","Recording every transaction as equal debits and credits — the self-checking foundation of all accounting."],["What is reconciliation?","Matching the books against bank/credit statements — proving the recorded cash equals real cash."],["Why cloud accounting over desktop?","Bank feeds, automatic backups, accountant access, and anywhere availability — the books stay current with less effort."]],"title":"Accounting Software","uses":["Small business: the complete books without an accounting department.","Month-end close: statements on demand.","Audit readiness: clean, traceable records."]},{"brief":"Invoicing and billing tools create professional invoices, chase payment, and accept online payment — turning completed work into collected cash faster.","examples":["A freelancer's invoice goes out with a 'Pay Now' button — paid in 2 days instead of 30, with automatic reminders at 7 and 14 days overdue.","A SaaS company's billing system meters usage, generates 10,000 monthly invoices, and retries failed cards automatically."],"history":["Paper invoices gave way to accounting-module billing; standalone tools (FreshBooks 2003) made invoicing delightful; Stripe Billing productized subscriptions.","Late-payment automation — reminders, penalties, dunning — turned collections from awkward to systematic."],"points":["Professional invoices: branding, line items, taxes, terms — sent by email with online payment links.","Recurring billing automates subscriptions and retainers — set once, billed forever, with proration for changes.","Dunning management retries failed payments and emails customers — recovering revenue that once required phone calls.","Aging reports show who owes what and how late — the cash-flow radar.","Integration with accounting posts paid invoices to the ledger automatically — no double entry."],"qa":[["What is dunning?","The systematic process of retrying failed payments and reminding customers — automated in modern billing systems."],["Why add 'Pay Now' buttons to invoices?","Because friction kills cash flow — one-click payment cuts days or weeks off collection."],["What is an aging report?","Receivables grouped by how overdue they are (current, 30, 60, 90+ days) — showing where collection effort goes."]],"title":"Invoicing and Billing","uses":["Freelancers: professional invoices that get paid fast.","Subscriptions: automated recurring billing at scale.","Cash flow: aging visibility and dunning."]},{"brief":"Payroll systems compute pay, withhold taxes, file returns, and pay employees — the highest-stakes routine transaction in business.","examples":["A 40-person company's payroll runs in 20 minutes: hours imported, taxes computed, direct deposits sent, filings queued.","A restaurant's tipped payroll handles tip credits, overtime, and multi-state withholding that spreadsheets could never manage."],"history":["Payroll service bureaus (ADP, 1949) outsourced the math; software (1990s) brought it in-house; cloud payroll (Gusto, 2012) made it self-service.","Tax-table automation and e-filing turned quarterly filings from a dreaded project into background processing."],"points":["Gross-to-net: hours × rates, overtime, bonuses, then federal/state/local withholding, Social Security, Medicare — computed per jurisdiction.","Tax filing: the system files 941s, W-2s, and state returns — missing a deadline means penalties, so automation matters.","Direct deposit, pay stubs, and employee self-service (W-4s, address changes) cut HR's routine workload.","Compliance: wage laws, overtime rules, and new-hire reporting vary by state — the system tracks what humans forget.","Contractor payments (1099s) ride alongside payroll — one system for all worker compensation."],"qa":[["What is the difference between gross and net pay?","Gross is earnings before deductions; net (take-home) is after taxes, benefits, and garnishments."],["Why is payroll the highest-stakes routine transaction?","Because errors hit people's livelihoods and tax mistakes bring penalties — accuracy and timeliness are non-negotiable."],["What does full-service payroll include?","Calculations, direct deposit, tax filings, W-2s, and new-hire reporting — the employer just approves hours."]],"title":"Payroll Systems","uses":["Every employer: accurate, timely, compliant pay.","Multi-state: jurisdiction rules handled automatically.","Contractors: 1099 payments alongside W-2 payroll."]},{"brief":"Inventory management tracks stock from purchase to sale — quantities, locations, reorder points — preventing both stockouts and dead capital.","examples":["A retailer sets reorder points: when widget stock hits 50 units, the system drafts a purchase order — no more empty shelves or emergency orders.","A manufacturer's system tracks 5,000 SKUs across 3 warehouses with lot numbers — a recall traces affected lots in minutes."],"history":["Cardex cards gave way to MRP (1970s); barcodes (1980s) made tracking real-time; RFID and cloud IMS brought it to small business.","Just-in-time (Toyota) made inventory a cost to minimize — the system balances availability against carrying cost."],"points":["SKUs, quantities, and locations are the core data — every receipt, sale, transfer, and adjustment updates the count.","Reorder points and safety stock automate purchasing — the math of demand variability vs lead time.","Lots, serials, and expiry dates enable traceability — recalls, warranties, and FIFO/FEFO rotation.","Cycle counting (continuous small counts) replaces annual wall-to-wall shutdowns — accuracy without stopping operations.","Valuation (FIFO, LIFO, average) ties inventory to the books — the balance sheet's stock number comes from here."],"qa":[["What is a reorder point?","The stock level triggering a new order — set so the order arrives before stock hits zero, covering lead-time demand plus safety stock."],["What is the difference between FIFO and FEFO?","FIFO ships oldest received first; FEFO ships earliest-expiring first — critical for perishables and pharma."],["Why cycle count instead of annual inventory?","Continuous small counts keep accuracy high year-round without the operational shutdown of a full physical count."]],"title":"Inventory Management","uses":["Retail: shelves stocked without overbuying.","Manufacturing: materials available for production.","Traceability: lots and serials for recalls."]},{"brief":"ERP systems unify finance, inventory, manufacturing, HR, and more in one database — the single source of truth for the whole enterprise.","examples":["A manufacturer's ERP links a sales order to production scheduling, material purchasing, shipping, and invoicing — one entry flows through everything.","Month-end close in an ERP: finance, inventory, and manufacturing subledgers reconcile automatically — no spreadsheet stitching."],"history":["MRP (1970s) → MRP II (1980s) → ERP (1990s, SAP/R3) — each wave integrated more functions; cloud ERP (NetSuite 1998) brought it midmarket.","ERP implementations became legendary for cost overruns — and for transforming companies that survived them."],"points":["One database: a sales order updates inventory, production, and finance simultaneously — no reconciliation between silos.","Modules (financials, SCM, manufacturing, HCM, CRM) share master data — customers, items, vendors defined once.","Workflows enforce process: purchase approvals, quality holds, and segregation of duties are systematized.","Implementation is organizational change, not IT — data cleanup, process redesign, and training decide success.","Cloud ERP cut the entry price — midsize companies now get integration once reserved for enterprises."],"qa":[["What makes ERP different from separate apps?","One shared database — transactions flow across functions automatically instead of being re-entered and reconciled."],["Why do ERP projects fail?","Treating them as software installs instead of business transformations — dirty data and unchanged processes doom them."],["What is master data?","The core shared records (customers, items, vendors) — one definition used by every module."]],"title":"ERP Systems","uses":["Manufacturing: order-to-cash fully integrated.","Multi-entity: consolidated finance across subsidiaries.","Growth: replacing the patchwork of disconnected apps."]},{"brief":"Business intelligence turns data into decisions — dashboards, reports, and ad-hoc analysis over the company's data warehouse.","examples":["A retail chain's BI dashboard shows same-store sales, traffic, and conversion by region — updated hourly, drilled to the store.","A hospital's BI tracks ER wait times by hour and triage level — staffing decisions driven by the data, not anecdote."],"history":["Executive information systems (1980s) were rigid; data warehousing (1990s) centralized data; self-service BI (Tableau 2003, Power BI 2015) put analysis in users' hands.","The modern data stack (cloud warehouses + dbt + BI) made BI fast, cheap, and current."],"points":["Dashboards monitor KPIs at a glance — designed for decisions, not decoration: every chart answers a question.","Data models (star schemas, semantic layers) define metrics once — 'revenue' means the same in every report.","Self-service lets analysts explore without IT tickets — governed by certified datasets, not chaos.","Alerting pushes anomalies to people — the dashboard watches so humans don't have to.","Data quality is the ceiling: BI on dirty data produces confident wrong answers — governance matters."],"qa":[["What is the difference between a dashboard and a report?","Dashboards monitor live KPIs interactively; reports present a fixed analysis for a point in time."],["What is a semantic layer?","Centralized metric definitions — ensuring 'revenue' and 'active customer' mean the same everywhere."],["Why does self-service BI need governance?","So explorers use certified data and definitions — freedom without anarchy."]],"title":"Business Intelligence and Dashboards","uses":["Executive oversight: KPI monitoring.","Operations: real-time performance visibility.","Analysis: ad-hoc exploration of business data."]},{"brief":"Data visualization translates numbers into pictures — charts chosen for the message, designed for instant comprehension.","examples":["A line chart shows website traffic doubling after the redesign — the trend obvious in one glance.","A heatmap of support tickets by hour and day reveals the Monday-morning surge — staffing adjusted accordingly."],"history":["Playfair's charts (1786) invented the form; Tufte (1983) defined the ethics; interactive visualization (D3, 2011) made it dynamic.","The chart-junk wars taught a generation that clarity beats decoration."],"points":["Chart choice is message choice: lines for trends, bars for comparisons, pies almost never, tables for exact values.","The data-ink ratio: maximize ink that carries data, minimize decoration — gridlines, 3D, and clip art are chartjunk.","Scales must be honest: truncated axes exaggerate; dual axes confuse — the visualization's ethics are in the scale.","Color encodes: sequential for magnitude, diverging for deviation, categorical for groups — with colorblind-safe palettes.","Interactivity (tooltips, filters, drill-down) lets one chart serve many questions."],"qa":[["When should you not use a pie chart?","Almost always — humans compare angles poorly; bars show the same proportions more accurately."],["What is chartjunk?","Decoration that carries no data — 3D effects, heavy gridlines, clip art — that obscures the message."],["Why do truncated axes mislead?","Because they exaggerate small differences — a 5% change looks like a doubling when the axis starts at 90."]],"title":"Data Visualization","uses":["Reporting: making metrics instantly readable.","Exploration: seeing patterns in data.","Persuasion: charts that drive decisions."]},{"brief":"Video conferencing replaced business travel for routine meetings — with etiquette, setup, and facilitation skills that make remote meetings work.","examples":["A distributed team's daily standup runs 15 minutes on video — cameras on, round-robin updates, blockers surfaced.","A sales demo shares screen, annotates the proposal live, and records for the absent stakeholder."],"history":["Expensive room systems (1990s) gave way to Skype (2003), then Zoom (2013) made video reliable; the 2020 pandemic made it universal.","Virtual backgrounds, captions, and AI summaries are the current polish on a mature medium."],"points":["Setup matters: camera at eye level, light on your face, decent mic — the biggest quality leaps are physical, not software.","Etiquette: mute when not speaking, cameras on for small meetings, chat for links and side notes.","Facilitation: agendas, round-robins, and explicit turn-taking replace hallway dynamics — silence means disengagement online.","Recording + AI summaries create searchable meeting records — the end of 'what did we decide?'","Fatigue is real: 25/50-minute defaults, camera-optional large meetings, and async video messages cut the load."],"qa":[["What is the biggest remote-meeting mistake?","No facilitation — without active hosting, remote meetings drift into silence or side-talk."],["Why do cameras matter in small meetings?","Nonverbal cues carry the conversation — cameras restore the feedback speakers need."],["When should a meeting be async instead?","Status updates and FYIs — record a video message; reserve live meetings for discussion and decisions."]],"title":"Video Conferencing","uses":["Remote teams: the daily meeting room.","Sales: demos without travel.","Interviews: hiring across geographies."]},{"brief":"Team chat replaced hallway talk and email threads — persistent, searchable, channel-organized conversation with the discipline to prevent chaos.","examples":["An incident channel coordinates an outage: timeline, commands, and decisions in one searchable thread — the postmortem writes itself.","A project's channel holds daily updates, file shares, and decisions — new members read the history and catch up."],"history":["IRC and IM were personal; HipChat/Slack (2013/14) made chat the team's OS; Teams (2017) bundled it with Office.","Threads, channels, and integrations turned chat from distraction into infrastructure."],"points":["Channels organize by topic/project — #proj-launch, #incident-2026 — searchable history beats buried email threads.","Threads keep side discussions from flooding channels — reply in thread, not in channel.","Integrations bring alerts, deploys, and approvals into chat — the team's nervous system.","Notification discipline: mentions for attention, channels muted by default, status/Do-Not-Disturb for focus.","Etiquette: searchable writing (clear subjects, conclusions first), no @channel unless truly urgent."],"qa":[["How do you prevent chat overload?","Channel discipline: default-mute channels, use threads, reserve @channel for true urgency, and set notification schedules."],["When should you use a thread vs the channel?","Thread for side discussions and follow-ups; channel only for announcements everyone must see."],["What belongs in chat vs email vs a doc?","Chat for quick coordination, email for formal records, docs for anything that needs drafting or permanence."]],"title":"Team Chat and Collaboration","uses":["Daily coordination: quick questions and updates.","Incidents: real-time war rooms.","Culture: the remote office's hallways."]},{"brief":"Cloud file storage replaced the file server — documents synced everywhere, shared by link, with version history that ends 'which copy is current' forever.","examples":["A proposal lives in one shared folder: the client sees the latest version via link, the team co-edits, history shows every change.","A photographer's 2TB archive syncs to the cloud — accessible from studio, laptop, and phone, safe from a stolen laptop."],"history":["File servers and USB drives ruled; Dropbox (2007) made sync effortless; Google Drive (2012) and OneDrive tied storage to productivity suites.","Ransomware made cloud version history a security feature — encrypted files rolled back in clicks."],"points":["Sync keeps local copies current across devices; selective sync saves disk on huge archives.","Sharing by link with view/comment/edit permissions replaced email attachments — one file, many viewers.","Version history and trash retention recover from overwrites, deletions, and ransomware.","Admin controls: sharing policies, device management, and audit logs for business tiers.","Backup vs sync: sync mirrors deletions — true backup needs separate versioned copies."],"qa":[["What is the difference between sync and backup?","Sync mirrors changes (including deletions) across devices; backup keeps independent versioned copies — you need both."],["How does link sharing replace attachments?","One live file shared by link — recipients always see the current version, no inbox-clogging copies."],["Why did ransomware make cloud storage a security tool?","Because version history lets you roll back encrypted files to pre-attack versions in minutes."]],"title":"Cloud File Storage","uses":["Team files: one current copy for everyone.","Client sharing: links instead of attachments.","Device independence: work from anywhere."]},{"brief":"Document management systems control the document lifecycle — creation, review, approval, retention — for regulated and quality-driven businesses.","examples":["A pharma SOP routes through draft → review → QA approval → effective — every signature recorded, superseded versions locked.","An engineering firm's DMS controls drawing revisions: only the current revision is downloadable, history preserved."],"history":["Paper document control (ISO 9001) digitized in the 1990s; SharePoint (2001) brought DMS to the masses; cloud DMS added e-signatures and workflows.","Regulated industries (pharma, finance) drove the strictest features: 21 CFR Part 11 electronic signatures."],"points":["Version control with check-in/check-out prevents conflicting edits on controlled documents.","Approval workflows route documents to reviewers in sequence — with electronic signatures where regulated.","Metadata and search find documents by properties (type, project, status), not just filenames.","Retention policies auto-archive or destroy per schedule — legal compliance, not manual cleanup.","Access control: who can view, edit, approve — the permissions matrix of the document estate."],"qa":[["What is the difference from cloud file storage?","DMS adds lifecycle control: approvals, controlled versions, retention, and audit trails — storage is just the shelf."],["What is 21 CFR Part 11?","The FDA rule for electronic records/signatures — requiring controls that make digital signatures legally equivalent to ink."],["Why lock superseded versions?","So nobody builds from an outdated SOP or drawing — only the current effective version is usable."]],"title":"Document Management Systems","uses":["Regulated industries: validated document control.","Engineering: drawing and spec revision control.","Quality systems: ISO 9001 document requirements."]},{"brief":"E-signature tools make agreements signable in minutes — legally binding signatures with audit trails, replacing print-sign-scan.","examples":["A sales contract is signed by both parties in 20 minutes — the rep sends from the CRM, the client signs on a phone.","An HR offer letter routes to the candidate, then to the hiring manager — fully executed without paper."],"history":["The ESIGN Act (2000) and eIDAS (EU) gave electronic signatures legal force; DocuSign (2003) productized the workflow.","Remote work made e-signature the default — paper signing is now the exception."],"points":["Legally binding in most jurisdictions — the audit trail (who, when, IP, document hash) proves the signature.","Workflows: sequential or parallel signers, fields, conditional routing — the signing ceremony designed per document.","Templates for NDAs, offers, and contracts turn routine agreements into one-click sends.","Integrations embed signing in CRM, HR, and procurement — signed where the work happens.","Certificate-based digital signatures add cryptographic identity for the highest-assurance cases."],"qa":[["Are e-signatures legally binding?","Yes — under laws like the US ESIGN Act and EU eIDAS, with audit trails proving signer identity and document integrity."],["What is the difference between e-signature and digital signature?","E-signature is the legal concept (intent to sign); digital signature is the cryptographic technology proving it."],["Why is the audit trail important?","It proves who signed, when, and that the document wasn't altered — the evidence if a signature is disputed."]],"title":"E-Signature Tools","uses":["Sales: contracts executed in minutes.","HR: offer letters and onboarding docs.","Procurement: vendor agreements at speed."]},{"brief":"PDF is business's final format — fixed-layout, printable, archivable — with workflows for creation, forms, redaction, and signing.","examples":["A report exports to PDF/A for the archive — fonts embedded, layout frozen, readable in 50 years.","A government form is a fillable PDF: fields, validation, and a submit button — paper process digitized."],"history":["Adobe's PDF (1993) solved cross-platform documents; Acrobat Reader's free distribution made it universal; ISO 32000 (2008) opened the standard.","PDF/A (archival), PDF/UA (accessibility), and PDF/X (print) specialized the format."],"points":["Creation: print-to-PDF or export from any app — the fixed-layout snapshot for distribution.","Editing: real PDF editors modify text, images, and pages — distinct from mere annotation.","Forms: fillable fields, calculations, and digital signatures turn PDFs into workflows.","Redaction permanently removes sensitive text — true redaction, not black boxes over selectable text.","PDF/A embeds everything for long-term archiving — the format of record for contracts and filings."],"qa":[["What is the difference between redaction and covering text?","True redaction removes the data; drawing black boxes over text leaves it selectable and copyable underneath."],["What is PDF/A?","The archival PDF variant — self-contained with embedded fonts, designed for decades of readability."],["When should you use PDF instead of a Word doc?","For final distribution: contracts, reports, forms — where layout must be fixed and content final."]],"title":"PDF Workflows","uses":["Final documents: contracts, reports, invoices.","Forms: fillable applications and surveys.","Archives: PDF/A for long-term records."]},{"brief":"Note-taking apps capture thinking — meeting notes, research, ideas — organized for retrieval, increasingly with AI assistance.","examples":["A consultant's meeting notes link to the project page, tag action items, and surface in search months later.","A researcher's web clips, PDFs, and annotations live in one searchable notebook — the external brain."],"history":["Paper notebooks digitized (OneNote 2003, Evernote 2008); wikis inspired linked notes; Roam/Notion (2010s) made bi-directional linking mainstream.","AI summarization and Q&A over notes is the current wave — ask your notes questions."],"points":["Capture fast: quick-add, mobile, web clipper — friction kills note systems.","Organization: folders/tags for structure, links for connections, search for retrieval — use all three.","Templates for meetings, projects, and journals standardize capture.","Linking (backlinks) turns notes into a knowledge graph — ideas connect across time.","AI features: summaries, action-item extraction, and natural-language search over your notes."],"qa":[["What is the difference between notes and docs?","Notes are personal capture and thinking; docs are shared, structured deliverables — different tools, different jobs."],["What are backlinks?","Automatic links showing which notes reference the current one — revealing connections you'd forgotten."],["Why do note systems fail?","Capture without retrieval — the fix is weekly review and search-first organization."]],"title":"Note-Taking Apps","uses":["Meeting notes: searchable decisions and actions.","Research: clipped sources with annotations.","Personal knowledge: the external brain."]},{"brief":"Password managers generate, store, and fill strong unique passwords — the single highest-leverage security tool in business.","examples":["An employee's 200 logins each get a 20-character random password — one master password (plus MFA) unlocks them all.","IT offboards a leaver in one click: shared vault access revoked, no password spreadsheet to hunt."],"history":["Browser-saved passwords were the insecure default; dedicated managers (1Password 2006, LastPass 2008) professionalized it.","Passkeys (2022+) promise to replace passwords — managers now broker the transition."],"points":["Unique random passwords per site — breach of one service never compromises others.","Autofill defeats phishing: the manager won't fill credentials on a fake domain.","Sharing: team vaults share logins without revealing passwords — access revocable per person.","MFA/TOTP built in: the manager stores second factors alongside passwords.","Admin: business tiers add policies, auditing, and offboarding — password hygiene at scale."],"qa":[["Why not reuse passwords?","Because breaches are routine — one leaked password unlocks every account that shares it."],["What is a passkey?","A cryptographic login replacing passwords — phishing-resistant, synced by your manager or platform."],["How do password managers help offboarding?","Shared credentials live in team vaults — revoke the person's access and they lose all of them instantly."]],"title":"Password Managers","uses":["Everyone: unique passwords without memorization.","Teams: shared logins without sticky notes.","Security: phishing resistance and breach containment."]},{"brief":"Business VPNs encrypt remote connections — securing work on untrusted networks and controlling access to company resources.","examples":["A traveling salesperson works from hotel Wi-Fi through the company VPN — traffic encrypted, internal apps reachable.","A contractor gets VPN access to only the staging servers — segmented, logged, revoked when the project ends."],"history":["VPNs secured dial-up and branch offices (1990s); remote work made them universal; zero-trust (2010s+) now challenges the castle-and-moat model.","WireGuard modernized the protocol — fast, simple, auditable."],"points":["Encryption protects traffic on untrusted networks — coffee-shop Wi-Fi becomes safe.","Site-to-site VPNs link offices into one private network over the internet.","Access control: who reaches which internal resources — the VPN as a gatekeeper.","Zero-trust evolution: verify every user and device per request, not just at the network edge.","Always-on vs on-demand: balancing security with battery and usability for mobile workers."],"qa":[["What does a VPN actually protect?","Eavesdropping on the local network and access control to private resources — not anonymity from websites."],["What is zero-trust networking?","Never trust the network location — authenticate every user, device, and request individually."],["Do remote workers still need VPNs?","For internal apps, yes — though zero-trust tools increasingly replace traditional VPN clients."]],"title":"VPNs for Business","uses":["Remote work: secure access to internal systems.","Travel: protection on untrusted networks.","Contractors: segmented, revocable access."]},{"brief":"Time tracking records where hours go — for billing, payroll, and productivity insight — with tools from simple timers to automatic activity capture.","examples":["An agency's designers start timers per client task — the week's 38 hours become an accurate client invoice.","A consultancy analyzes tracked time: 30% on admin — the data justifies hiring an operations assistant."],"history":["Paper timesheets gave way to digital (1990s); Toggl (2006) made tracking painless; automatic tracking (RescueTime, 2008) removed manual entry.","Billable-hour businesses drove adoption — time is literally the product."],"points":["Manual timers: start/stop per task — accurate when disciplined, fiction when reconstructed Friday afternoon.","Automatic tracking: apps log active windows and categorize — the honest baseline.","Billable vs non-billable: the agency's core distinction — utilization rates drive hiring and pricing.","Approvals: managers review and approve timesheets before payroll and invoicing.","Analytics: capacity planning, project costing, and productivity patterns from the data."],"qa":[["Why do timesheets fail?","Reconstructed from memory — the fix is in-the-moment tracking and same-day review."],["What is utilization rate?","Billable hours ÷ total hours — the agency's key metric for staffing and profitability."],["Is automatic tracking surveillance?","It can feel so — transparent policies and personal-productivity framing keep it ethical."]],"title":"Time Tracking","uses":["Agencies: billing clients accurately.","Payroll: hourly worker hours.","Productivity: understanding where time goes."]},{"brief":"Expense management digitizes the receipt-to-reimbursement cycle — capture, categorize, approve, pay — ending the shoebox of receipts.","examples":["A salesperson photographs receipts at dinner — OCR reads the total, the expense submits, the manager approves from a phone.","Finance's dashboard flags a duplicate submission and an out-of-policy hotel — caught before reimbursement."],"history":["Paper expense reports with stapled receipts gave way to Concur (1993); mobile capture (Expensify 2008) made it real-time.","Corporate cards with auto-import turned expense reports into exception-handling."],"points":["Mobile capture: photograph receipts at purchase — OCR extracts vendor, amount, date.","Policy engines flag out-of-policy spend automatically — enforcement before payment, not after.","Approval chains route by amount and department — managers approve from anywhere.","Corporate card feeds auto-import transactions — employees categorize, not transcribe.","Reimbursement via ACH/direct deposit — days, not weeks."],"qa":[["What is OCR in expense tools?","Optical character recognition reading receipt photos — extracting vendor, date, and total automatically."],["Why integrate corporate cards?","Transactions import automatically — the expense report becomes categorization, not data entry."],["How do policies get enforced?","Rules flag violations at submission — the system, not finance's memory, knows the hotel cap."]],"title":"Expense Management","uses":["Travelers: painless receipt capture.","Finance: policy enforcement and visibility.","Speed: reimbursements in days."]},{"brief":"HRIS platforms centralize employee data — records, org charts, time off, benefits — the system of record for the workforce.","examples":["A new hire's record flows from the ATS to the HRIS to payroll and IT provisioning — one entry, everything set up.","An employee checks PTO balance, requests a day, and enrolls in benefits — all self-service, no HR ticket."],"history":["Personnel file cabinets digitized in the 1990s (PeopleSoft); cloud HRIS (Workday 2005, BambooHR 2008) brought it to every size company.","Employee self-service shifted routine HR work from HR staff to employees."],"points":["Core records: personal data, employment history, compensation, documents — one source of truth.","Org charts and reporting lines generated from the data — always current.","Time-off tracking: balances, requests, approvals — the end of spreadsheet PTO.","Benefits administration: enrollment, life events, carrier feeds.","Reporting: headcount, turnover, diversity, compensation — workforce analytics from clean data."],"qa":[["What is the difference between HRIS and payroll?","HRIS is the employee system of record; payroll computes pay — they integrate, with HRIS feeding payroll."],["What is employee self-service?","Employees updating their own info, requesting time off, enrolling in benefits — cutting HR's transactional load."],["Why is clean HR data critical?","Because headcount, compensation, and compliance reporting all derive from it — garbage in, garbage out."]],"title":"HR and HRIS Software","uses":["Employee records: the workforce system of record.","Self-service: time off, benefits, info updates.","Analytics: headcount, turnover, compensation."]},{"brief":"Applicant tracking systems manage hiring pipelines — job postings, resumes, interviews, offers — turning chaotic email hiring into a fair, trackable process.","examples":["A 200-applicant posting auto-screens for required certifications — recruiters interview the 15 qualified, not the 200.","Interview scorecards in the ATS compare candidates on the same rubric — reducing bias, improving hires."],"history":["Paper resumes and file folders gave way to resume databases (1990s); Taleo (1996) and cloud ATS made structured hiring standard.","AI screening and scheduling automation are the current frontier — with bias audits following close behind."],"points":["Pipeline stages (applied → screen → interview → offer → hired) mirror sales pipelines — hiring as a managed funnel.","Resume parsing extracts structured data from PDFs — searchable, filterable candidate records.","Interview kits: standardized questions and scorecards per role — consistency and legal defensibility.","Scheduling automation ends email ping-pong — candidates self-book from interviewer availability.","Compliance: EEO data, disposition records, and audit trails satisfy employment law."],"qa":[["What is a hiring pipeline?","The staged funnel candidates move through — sourcing to offer — managed like a sales pipeline."],["Why standardize interviews?","Fairness and prediction: structured interviews with scorecards predict performance better and reduce bias."],["What ATS compliance matters?","Record-keeping for EEO, disposition reasons, and data retention — the legal backbone of hiring."]],"title":"Recruiting and Applicant Tracking","uses":["Hiring at scale: managing hundreds of applicants per role.","Fair process: structured, documented decisions.","Talent pools: past candidates searchable for new roles."]},{"brief":"Performance review software structures feedback cycles — goals, check-ins, reviews, calibration — making growth conversations regular instead of annual surprises.","examples":["Quarterly OKRs cascade from company to team to individual — everyone sees how their work connects.","A 360 review gathers peer feedback on collaboration — the manager's view plus the team's."],"history":["Annual appraisals (mid-20th century) proved dreaded and useless; continuous performance management (2010s) replaced them with frequent check-ins.","OKRs (Intel/Google) made goal transparency the modern standard."],"points":["Goal frameworks (OKRs, SMART) align individual work with company objectives — visible to all.","Continuous check-ins replace the annual review — frequent small corrections beat yearly surprises.","360/peer feedback captures collaboration quality the manager can't see.","Calibration sessions align ratings across teams — fairness at scale.","Development plans turn review insights into growth actions — the point is improvement, not judgment."],"qa":[["What are OKRs?","Objectives and Key Results — ambitious objectives with measurable key results, set quarterly and visible company-wide."],["Why replace annual reviews?","Because yearly feedback is too late to change behavior — frequent check-ins coach in real time."],["What is calibration?","Managers aligning ratings across teams so 'exceeds' means the same everywhere — fighting grade inflation."]],"title":"Performance Reviews and OKRs","uses":["Alignment: everyone pulling toward company goals.","Coaching: regular feedback conversations.","Growth: development plans from review insights."]},{"brief":"Learning management systems deliver and track training — courses, certifications, compliance — proving the workforce is qualified.","examples":["A hospital's LMS assigns annual HIPAA training to 2,000 staff — completions tracked, reminders automatic, auditors satisfied.","A sales team's LMS delivers product certification: video lessons, quizzes, and a scored demo — certified reps sell more."],"history":["Corporate training classrooms gave way to e-learning (2000s, SCORM); cloud LMS made it mobile and social.","Microlearning and AI tutoring are shrinking training from courses to moments."],"points":["Course delivery: video, documents, quizzes, and live sessions — blended learning paths.","Compliance tracking: required training with deadlines, reminders, and completion proof for auditors.","Certifications: structured programs with assessments — qualified vs not, no ambiguity.","Analytics: completion rates, scores, and skill gaps — training ROI visible.","Authoring: building courses from existing content — SMEs become course creators."],"qa":[["What is SCORM?","The e-learning content standard — courses built once play in any compliant LMS."],["Why does compliance training need an LMS?","Proof: regulators require documented completion — the LMS is the evidence system."],["What is microlearning?","Short focused lessons (minutes) delivered at the moment of need — higher retention than day-long courses."]],"title":"Learning Management Systems","uses":["Compliance: provable required training.","Onboarding: structured new-hire learning.","Upskilling: continuous workforce development."]},{"brief":"Marketing automation nurtures leads at scale — email sequences, scoring, and handoffs triggered by behavior, not manual effort.","examples":["A trial signup triggers a 7-email onboarding sequence — tips timed to usage milestones, upgrading 20% to paid.","A whitepaper download scores +10; pricing-page visit scores +25 — at 50 points, sales gets the lead automatically."],"history":["Email blasts gave way to drip campaigns (2000s); HubSpot (2006) and Marketo productized inbound automation.","AI now writes variants, predicts send times, and scores with models humans can't build."],"points":["Drip sequences: timed, behavior-triggered email series — nurture without manual sending.","Lead scoring: fit + engagement = priority — sales focuses where automation qualifies.","Segmentation: the right message per persona, stage, and behavior — relevance at scale.","CRM handoff: scored, enriched leads route to sales with full engagement history.","Attribution: which campaigns sourced pipeline — marketing's proof of revenue impact."],"qa":[["What is lead nurturing?","Building relationships with not-yet-ready buyers through valuable touches — so you're chosen when they're ready."],["What is marketing attribution?","Crediting revenue to the campaigns and touches that influenced it — proving marketing's ROI."],["When does automation become spam?","When it's batch-and-blast without relevance — automation must serve the recipient, not just the sender's quota."]],"title":"Marketing Automation","uses":["Lead nurturing: scaling follow-up.","Demand gen: campaigns that source pipeline.","Alignment: scored handoffs to sales."]},{"brief":"Email marketing remains the highest-ROI digital channel — owned audience, direct reach, measurable everything — run with professional tools, not BCC.","examples":["A retailer's weekly newsletter drives 30% of online revenue — segmented by purchase history, personalized per customer.","A B2B webinar invite sequence fills 500 seats: invite, reminder, last-chance, replay — each tracked."],"history":["Bulk email (1990s) → CAN-SPAM (2003) legitimized it → Mailchimp (2001) democratized design → automation and AI personalized it.","Deliverability became a discipline as inboxes filtered aggressively."],"points":["List building: opt-in forms, lead magnets, and preference centers — the owned audience asset.","Segmentation and personalization: behavior-based targeting beats batch-and-blast on every metric.","Automation: welcome series, abandoned cart, win-back — revenue on autopilot.","Deliverability: authentication (SPF/DKIM/DMARC), list hygiene, and engagement — reaching the inbox, not spam.","Testing: subject lines, content, and send times — the metrics (open, click, conversion) guide every decision."],"qa":[["Why is email the highest-ROI channel?","Owned audience, near-zero marginal cost, direct attribution — no algorithm between you and the subscriber."],["What is deliverability?","The art and science of reaching the inbox — authentication, reputation, and engagement vs spam filters."],["What is a welcome series?","Automated onboarding emails for new subscribers — the highest-engagement emails you'll ever send."]],"title":"Email Marketing","uses":["E-commerce: newsletters and cart recovery driving revenue.","B2B: nurture and event promotion.","Media: audience relationships direct."]},{"brief":"Social media management tools schedule, publish, monitor, and measure across networks — turning chaotic posting into a content operation.","examples":["A brand's month of posts is scheduled in one sitting — queued per network, auto-published at audience-peak times.","Social listening flags a complaint spike about a product defect — support responds before it trends."],"history":["Native posting gave way to Hootsuite (2008) multi-network scheduling; listening (Radian6) and employee advocacy followed.","Video-first algorithms and social commerce made scheduling plus analytics essential."],"points":["Scheduling and queues: plan once, publish across networks at optimal times.","Listening: monitoring mentions, sentiment, and competitors — the market's unfiltered voice.","Engagement: unified inboxes for comments and DMs — response time as a metric.","Analytics: reach, engagement, and conversion per post — content strategy from data.","Approval workflows: brand-safe publishing with review chains for regulated industries."],"qa":[["What is social listening?","Monitoring social conversations for brand mentions, sentiment, and trends — market research in real time."],["Why schedule instead of posting natively?","Consistency, timing optimization, and team workflow — plus cross-network analytics in one place."],["What metric matters most?","Depends on goal — engagement for brand, clicks/conversions for performance — vanity reach alone misleads."]],"title":"Social Media Management","uses":["Brand building: consistent multi-network presence.","Customer care: social as a support channel.","Campaigns: launches coordinated everywhere."]},{"brief":"SEO tools reveal how search sees your site — rankings, technical health, keywords, and backlinks — guiding the long game of organic traffic.","examples":["A site audit finds 2,000 pages with duplicate titles — fixed in a sprint, organic traffic up 40% in three months.","Keyword research shows 'accounting software for freelancers' has volume and weak competition — the content plan writes itself."],"history":["Webmaster logs gave way to Google Search Console (2006); Moz/Ahrefs/Semrush (2000s-10s) built the commercial toolkit.","Core Web Vitals and AI overviews keep rewriting the rules — the tools track what matters now."],"points":["Technical audits: crawl errors, speed, mobile, structured data — the health check.","Keyword research: volume, difficulty, intent — what to target and why.","Rank tracking: positions over time per keyword and location — the scoreboard.","Backlink analysis: who links to you (and competitors) — authority mapped.","Content optimization: briefs and scoring that align pages with search intent."],"qa":[["What is technical SEO?","Making the site crawlable, fast, and understandable — the foundation all content SEO builds on."],["Why do backlinks matter?","They're authority votes — quality links from trusted sites remain a top ranking factor."],["What are Core Web Vitals?","Google's page-experience metrics (loading, interactivity, stability) — user experience as a ranking input."]],"title":"SEO Tools","uses":["Organic growth: the compounding traffic channel.","Content strategy: data-driven topic planning.","Technical health: keeping the site search-ready."]},{"brief":"Web analytics measures what visitors do — traffic sources, behavior, conversions — turning the website from a brochure into an instrument.","examples":["Funnel analysis shows 70% checkout abandonment at shipping options — a free-shipping threshold recovers millions.","A content team learns 80% of blog traffic goes to 10 posts — the update priority writes itself."],"history":["Log analyzers gave way to Google Analytics (2005, free) — analytics for everyone; GA4 (2020) rebuilt it event-first for privacy.","Server-side tracking and consent management are the current adaptation to privacy regulation."],"points":["Events over pageviews: modern analytics tracks actions (clicks, signups, purchases) — the behavior that matters.","Funnels and cohorts: where users drop off, how groups behave over time — diagnosis, not just counting.","Attribution: which channels drive conversions — budget follows evidence.","Privacy: consent modes, anonymization, and first-party data — analytics within regulation.","Dashboards for decisions: traffic, conversion, and revenue trends the team actually watches."],"qa":[["What is the difference between sessions and users?","Users are people (devices); sessions are visits — one user, many sessions."],["What is a conversion funnel?","The staged path to a goal (visit → cart → checkout) — showing where prospects drop off."],["Why did analytics go event-first?","Because pageviews can't describe apps — events model any interaction on any platform."]],"title":"Web Analytics","uses":["E-commerce: conversion optimization.","Content: what audiences actually read.","Marketing: channel ROI evidence."]},{"brief":"E-commerce platforms power online stores — storefront, cart, checkout, payments — from side hustles to enterprises.","examples":["A maker launches on Shopify in a weekend: theme, products, Stripe — selling by Monday.","An enterprise replatforms to headless commerce: the same backend serving web, app, and in-store kiosks."],"history":["Yahoo Stores/osCommerce (early 2000s) → Shopify (2006) democratized stores → headless/API commerce decoupled frontend from backend.","Social and mobile checkout keep compressing the path from discovery to purchase."],"points":["Storefront: themes and page builders — brand expression without developers (until you need them).","Cart and checkout: the money pages — one-page checkout, guest options, and trust signals convert.","Payments: integrated processing (cards, wallets, BNPL) — the platform's cut vs your gateway.","Apps/extensions: reviews, upsells, subscriptions, and shipping — the ecosystem extends the core.","Headless: API-first backends feeding custom frontends — maximum flexibility, developer required."],"qa":[["What is headless commerce?","Decoupling the storefront from the backend via APIs — custom experiences powered by a commerce engine."],["Why does checkout design matter so much?","Because most carts abandon — every friction point (forced accounts, surprise shipping) costs revenue."],["What is BNPL?","Buy Now Pay Later — installment payments at checkout that lift conversion, especially for higher tickets."]],"title":"E-Commerce Platforms","uses":["Retail online: the digital storefront.","DTC brands: owned customer relationships.","Omnichannel: one backend, many touchpoints."]},{"brief":"Point-of-sale systems run the checkout — sales, payments, inventory, and staff — the operational heart of retail and hospitality.","examples":["A café's POS fires orders to the kitchen display, tracks the lunch rush, and reconciles the register at close.","A boutique's POS knows the regular: purchase history, loyalty points, and sizes — the sale is personal."],"history":["Cash registers (1879) → electronic POS (1970s) → iPad POS (Square 2009) democratized it → cloud POS unified online and in-store.","Contactless and mobile wallets rewrote the payment moment."],"points":["Checkout: fast sales, discounts, returns — speed is the metric at the register.","Payments: cards, contactless, gift cards, split tenders — the money in.","Inventory: stock decrements per sale — the shelf truth.","Staff: clock-in, permissions, and performance — the team managed.","Omnichannel: buy online/pickup in store, endless aisle — one inventory, every channel."],"qa":[["What is endless aisle?","Selling the full catalog in-store via kiosk/tablet — the shelf extends to the warehouse."],["Why did iPad POS disrupt retail tech?","Cost and simplicity — a capable POS for hundreds, not tens of thousands, of dollars."],["What is BOPIS?","Buy Online, Pickup In Store — the omnichannel fulfillment customers now expect."]],"title":"Point of Sale (POS) Systems","uses":["Retail: the checkout and inventory truth.","Restaurants: orders, kitchen, and payments.","Services: bookings with payment."]},{"brief":"Helpdesk software turns support chaos into a managed queue — tickets, SLAs, knowledge bases, and metrics that prove customers are cared for.","examples":["A SaaS support team triages 500 daily tickets: auto-tagged, SLA-timed, macro-answered — CSAT at 96%.","A customer's 'how do I reset' search hits the knowledge base first — deflected from the queue entirely."],"history":["Phone banks gave way to email queues (1990s); Zendesk (2007) made helpdesk beautiful; AI triage and deflection are the current wave.","SLAs turned support from a cost center into a measured service with contractual teeth."],"points":["Ticketing: every request tracked, prioritized, assigned — nothing lost, nothing duplicated.","SLAs: response and resolution targets per priority — the contract with the customer.","Knowledge base: self-service answers deflect tickets — the cheapest resolution is no ticket.","Macros and automation: one-click answers for common issues, routing by topic and sentiment.","Metrics: CSAT, first-response time, resolution time — support quality made visible."],"qa":[["What is a ticket SLA?","The promised response/resolution time per priority — e.g., critical issues answered in 15 minutes."],["What is ticket deflection?","Resolving issues via knowledge base or AI without an agent — the most efficient support."],["Why measure CSAT?","Customer satisfaction after each interaction — the direct verdict on support quality."]],"title":"Customer Support and Helpdesk","uses":["SaaS: support at scale with quality metrics.","E-commerce: order and product help.","IT: internal employee support."]},{"brief":"Live chat and messaging put support inside the product and website — instant, contextual help where customers already are.","examples":["A checkout page's chat answers a shipping question in 30 seconds — the sale saved.","An app's in-product messenger opens with the user's account context — no 'what's your email' dance."],"history":["Website chat widgets (2000s) → proactive chat triggers → in-app messaging (Intercom 2011) → AI chatbots handling the routine.","Messaging apps (WhatsApp Business) extended chat to where customers live."],"points":["Proactive triggers: chat offers help on pricing pages or stuck checkouts — timed by behavior.","Context: the agent sees the page, cart, or account — support without interrogation.","Chatbots handle the routine (hours, status, resets) — humans take the complex.","Transcripts and CRM logging: every chat becomes part of the customer record.","Mobile messaging: WhatsApp, SMS, and Apple Messages as support channels."],"qa":[["When does proactive chat help vs annoy?","Help on high-intent pages (pricing, checkout); annoy as popups on first visit — timing is everything."],["What should chatbots handle?","The frequent and simple — hours, order status, password resets — escalating the rest with context."],["Why in-app messaging beats email for SaaS?","Context and immediacy — the conversation happens where the problem is, with account data attached."]],"title":"Live Chat and Messaging","uses":["E-commerce: saving sales at the moment of doubt.","SaaS: in-product contextual help.","Support: instant channel alongside tickets."]},{"brief":"Survey tools collect structured feedback — NPS, CSAT, employee engagement, market research — turning opinions into data.","examples":["A post-purchase NPS survey scores 62 — promoters identified for reviews, detractors routed to support.","An employee engagement pulse runs quarterly: 12 questions, trends by department, action plans from the data."],"history":["Paper questionnaires gave way to SurveyMonkey (1999); Typeform (2012) made surveys delightful; embedded micro-surveys now capture feedback in context.","NPS (2003) gave business one loyalty number to rule them all."],"points":["Question design: unbiased wording, right scales, no leading questions — garbage questions, garbage data.","NPS/CSAT/CES: the standard loyalty metrics — tracked over time, benchmarked.","Distribution: email, link, embed, in-app — reaching respondents where they are.","Analysis: crosstabs, trends, and text analysis turn responses into insight.","Response discipline: short surveys, clear purpose, closed feedback loops — respect earns responses."],"qa":[["What is NPS?","Net Promoter Score — % promoters minus % detractors on the 0-10 'would recommend' question — the loyalty benchmark."],["Why do surveys fail?","Too long, biased questions, and no visible action on results — respondents learn their input vanishes."],["What is a good response rate?","Depends on channel — in-app micro-surveys can hit 20%+; cold email surveys celebrate 5%."]],"title":"Survey Tools","uses":["Customer loyalty: NPS tracking.","Employee engagement: pulse surveys.","Research: market and UX feedback."]},{"brief":"Form builders digitize paper processes — applications, registrations, intakes — with validation, logic, and integrations, no coding required.","examples":["A clinic's intake form branches by symptoms — the right questions per patient, submitted straight to the EHR.","An event registration form takes 500 signups with meal choices and payments — the attendee list builds itself."],"history":["Paper forms → PDF forms → web builders (Wufoo 2006, JotForm 2006, Google Forms 2008) → logic-driven workflow forms.","E-signature integration closed the loop from form to agreement."],"points":["Drag-and-drop building: fields, validation, and layouts without code.","Conditional logic: show the right fields per answers — forms that think.","Payments: collecting fees, deposits, and donations in the form.","Integrations: submissions flow to CRM, sheets, and email — the form as a workflow trigger.","Security: HIPAA, encryption, and access control for sensitive data."],"qa":[["What is conditional logic in forms?","Showing/hiding fields based on answers — the form adapts instead of showing everything to everyone."],["When is a form builder better than a custom form?","For standard processes — speed wins; custom code only when the workflow is truly unique."],["How do forms stay compliant?","Encryption, access controls, and compliance modes (HIPAA) for sensitive data collection."]],"title":"Form Builders","uses":["Intake: clients, patients, applicants.","Events: registration with payments.","Operations: digitizing paper processes."]},{"brief":"Workflow automation connects apps — when this happens, do that — eliminating copy-paste between tools without developers.","examples":["New CRM lead → auto-create Slack notification, add to email sequence, and create a task — the follow-up machine.","A form submission posts to Sheets, notifies the team, and files the document — the process runs itself."],"history":["Enterprise EAI was expensive; Zapier (2011) democratized 'if this then that' for business apps.","AI steps now let automations summarize, classify, and draft — beyond rote copying."],"points":["Triggers and actions: the grammar — a new row triggers, five apps act.","Multi-step workflows: branches, filters, and delays model real processes.","Error handling: failed runs alert and retry — automations need operations, not just setup.","Popular patterns: lead routing, notifications, data sync, content publishing, approvals.","Limits: automations encode today's process — review when the process changes, or they fossilize bad habits."],"qa":[["What is the difference from an integration?","Integrations connect two apps deeply; automation platforms orchestrate many apps' triggers and actions visually."],["When should you automate vs integrate natively?","Automate cross-app glue quickly; build native integrations for core, high-volume flows."],["What breaks automations?","API changes, renamed fields, and process changes — monitor runs and version your workflows."]],"title":"Workflow Automation","uses":["Lead handling: instant routing and follow-up.","Notifications: the right alerts to the right people.","Data sync: keeping apps consistent."]},{"brief":"No-code databases give teams structured data apps — custom CRMs, trackers, and portals — built visually, not programmed.","examples":["A nonprofit tracks 1,000 donors in Airtable: linked records, filtered views per fundraiser, forms for new gifts.","A team's project hub in Notion databases: tasks linked to projects linked to clients — the company wiki as a database."],"history":["FileMaker (1980s) and Access (1992) were the originals; Airtable (2012) and Notion (2016) made databases beautiful and collaborative.","No-code turned 'we need an app for that' from a six-month project into an afternoon."],"points":["Tables, linked records, and views: relational concepts without SQL.","Views per role: the same data as kanban, calendar, or gallery — each team sees its lens.","Forms feed the database — structured capture from anyone.","Automations: reminders, status changes, and notifications on data events.","Limits: thousands of records fine, millions need real databases — know the ceiling."],"qa":[["When is no-code enough vs a real database?","Team-scale structured work (thousands of rows) — no-code wins; millions of rows or complex logic needs engineering."],["What are linked records?","Relationships between tables — a task linked to its project — the relational model made visual."],["Why do no-code databases spread so fast?","Because the person with the problem builds the solution — no ticket queue, no waiting."]],"title":"No-Code Databases","uses":["Custom trackers: built by the teams that need them.","Lightweight CRMs: tailored pipelines.","Intranets: wikis that are actually databases."]},{"brief":"Business VoIP replaced desk phones with internet calling — softphones, auto-attendants, and call analytics at a fraction of legacy cost.","examples":["A 30-person company runs entirely on softphones: auto-attendant routes, call queues, and voicemail-to-email — no PBX closet.","A support team's call data shows peak hours and missed calls — staffing adjusted, callbacks automated."],"history":["PBX closets and PRI lines gave way to hosted VoIP (2000s); RingCentral/8x8 productized it; Teams/Zoom Phone (2020s) bundled voice with collaboration.","The pandemic finished the desk phone — headsets and apps won."],"points":["Hosted PBX: auto-attendants, extensions, and queues without hardware.","Softphones and mobile apps: the desk phone is now software.","Call analytics: volume, wait times, and recordings — the phone system as a data source.","Integrations: screen-pops from the CRM — the agent sees the caller before answering.","Reliability: QoS, failover to mobile, and e911 — voice as critical infrastructure."],"qa":[["What is a softphone?","Phone software on computer or mobile — calls over the internet, no desk hardware."],["Why did businesses abandon desk phones?","Cost, flexibility, and features — hosted VoIP does more for less, anywhere."],["What is voicemail-to-email?","Voicemails transcribed and emailed — the inbox absorbs the phone."]],"title":"Business Phone Systems (VoIP)","uses":["Offices: full phone systems without hardware.","Support: queues and analytics.","Remote teams: business calling from anywhere."]},{"brief":"Virtual data rooms secure sensitive document sharing — M&A due diligence, fundraising, and legal review — with permissions, watermarks, and audit trails.","examples":["An acquisition's data room holds 10,000 documents: buyers see financials, lawyers see contracts — each with watermarks and expiry.","A startup's fundraising room shares the deck, model, and cap table — access revoked per investor after the round."],"history":["Physical deal rooms (bankers' boxes, supervised access) gave way to VDRs (2000s); the pandemic made them the default for every deal.","AI redaction and document analytics are the current edge."],"points":["Granular permissions: who sees which folders — need-to-know enforced.","Dynamic watermarks: viewer identity on every page — deterring leaks.","Audit trails: every view, download, and print logged — the deal's evidence.","Q&A modules: buyer questions routed and answered in the room.","Expiry and revocation: access ends when the deal does."],"qa":[["When is a data room needed over cloud sharing?","For sensitive multi-party diligence — M&A, fundraising, litigation — where control and audit trails are non-negotiable."],["What do dynamic watermarks do?","Stamp each viewer's identity on documents — making leaks traceable and deterring them."],["Why audit trails matter in deals?","They prove what was disclosed to whom and when — the legal record of diligence."]],"title":"Virtual Data Rooms","uses":["M&A: due diligence at scale.","Fundraising: controlled investor access.","Legal: privileged document review."]},{"brief":"Contract lifecycle management tracks agreements from draft to renewal — repository, approvals, obligations, and deadlines — so no renewal surprises anyone.","examples":["A 500-contract repository alerts 90 days before each renewal — renegotiations planned, auto-renewals caught.","Sales contracts route: rep drafts → legal approves → client e-signs → obligations (SLAs, discounts) tracked automatically."],"history":["Shared drives full of PDFs gave way to CLM (2000s); AI extraction (2010s) made legacy contracts searchable.","Obligation tracking turned contracts from filed paper into managed commitments."],"points":["Central repository: every agreement searchable — the end of 'where is that contract?'","Drafting: clause libraries and templates — legal-approved starting points.","Approval workflows: the right reviewers per contract type and value.","Obligation tracking: renewals, SLAs, and milestones — commitments monitored, not forgotten.","AI extraction: key terms pulled from legacy PDFs — the backfile made useful."],"qa":[["What is contract lifecycle management?","Managing agreements from request through drafting, approval, execution, and renewal — the full journey."],["Why do auto-renewals surprise companies?","Because nobody tracked the date — CLM alerts turn surprises into planned decisions."],["What does AI extraction do?","Reads legacy contract PDFs and pulls parties, dates, values, and terms into searchable fields."]],"title":"Contract Management","uses":["Legal: the agreement system of record.","Procurement: vendor terms tracked.","Sales: faster contracting cycles."]},{"brief":"Business continuity and backup tools ensure survival — automated backups, disaster recovery, and continuity plans for ransomware, outages, and disasters.","examples":["Ransomware encrypts the file server at 2am — the 1am backup restores by 9am, the ransom never considered.","A hurricane closes headquarters — the continuity plan has the team on cloud systems from home by noon."],"history":["Tape rotations gave way to disk and cloud backup; ransomware (2010s) made immutable backups essential; continuity planning matured post-pandemic.","The 3-2-1 rule evolved: 3 copies, 2 media, 1 offsite — plus 1 immutable."],"points":["Automated backups: scheduled, tested, and monitored — untested backups are wishes.","Immutable copies: backups ransomware can't alter — the last line of defense.","Disaster recovery: RTO/RPO targets define how fast and how much data — the recovery contract.","Continuity plans: people, processes, and alternates — the playbook for operating through disruption.","Testing: restore drills prove the plan — annually at minimum, tabletop exercises included."],"qa":[["What is the 3-2-1 backup rule?","3 copies, 2 different media, 1 offsite — plus immutability against ransomware."],["What are RTO and RPO?","Recovery Time Objective (how fast) and Recovery Point Objective (how much data loss) — the DR targets."],["Why test restores?","Because backups fail silently — only a restore proves the data is actually recoverable."]],"title":"Business Continuity and Backup","uses":["Ransomware defense: immutable recovery.","Disaster recovery: systems back within targets.","Continuity: operating through disruption."]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief,genre:angle,type:RECORD_KIND,content:content, content_completeness:'stub',
    stub_note:'Topic stub: the topic title and its one-line brief are real; the full guide article is not yet written. This record does not present shell text as a complete guide.',demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-business-tools-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('business-tools',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();